<template><section><span class="page-kicker">My account</span><h1 class="page-title">My registered details</h1><StatusMessage :message="error" error retry @retry="load"/><StatusMessage :message="success"/><p v-if="loading" role="status">Loading profile...</p><div v-else-if="profile" class="panel"><h2>{{ profile.fullName }}</h2><dl><dt>Mobile</dt><dd>{{ profile.mobileNumber }}</dd><dt>Email</dt><dd>{{ profile.email || 'Not provided' }}</dd><dt>Status</dt><dd>{{ profile.status }}</dd></dl><form v-if="can('MEMBER_UPDATE','SELF')||can('MEMBER_UPDATE','SOCIETY')" @submit.prevent="save"><h3 class="section-title">Update registered details</h3><fieldset class="plain-fieldset" :disabled="busy"><Input name="profileFullName" label="Full name" v-model="form.fullName" maxlength="160" autocomplete="name" required/><Input name="profileMobile" label="Mobile number" hint="10 digits, starting with 6, 7, 8 or 9." v-model="form.mobileNumber" type="tel" pattern="[6-9][0-9]{9}" autocomplete="tel" required/><Input name="profileEmail" label="Email address (optional)" v-model="form.email" type="email" maxlength="254" autocomplete="email"/><button class="button" :disabled="busy">{{ busy?'Saving...':'Save my details' }}</button></fieldset></form><p v-else>Contact your society administrator to change registered details or ownership.</p><router-link :to="'/members/'+profile.memberId+'/memberships'">My membership history</router-link></div><p v-else-if="!error">Your login account is not linked to a registered person.</p></section></template>
<script>
import {api,errorMessage} from '../services/api';import {memberPayload} from '../util/contracts.cjs';import access from '../util/access-mixin';import Input from '../components/forms/Input.vue';import StatusMessage from '../components/StatusMessage.vue';
export default {mixins:[access],components:{Input,StatusMessage},data:()=>({profile:null,form:{fullName:'',mobileNumber:'',email:''},error:'',success:'',loading:false,busy:false}),created(){this.load()},methods:{async load(){this.loading=true;this.error='';try{const id=this.currentUser.memberId;if(id){this.profile=await api.get('members',id);this.form={fullName:this.profile.fullName,mobileNumber:this.profile.mobileNumber,email:this.profile.email||''}}}catch(e){this.error=errorMessage(e)}finally{this.loading=false}},async save(){if(this.busy||!(this.can('MEMBER_UPDATE','SELF')||this.can('MEMBER_UPDATE','SOCIETY')))return;this.busy=true;this.error='';this.success='';try{this.profile=await api.save('members',this.profile.memberId,memberPayload(this.form),this.profile._etag);this.form={fullName:this.profile.fullName,mobileNumber:this.profile.mobileNumber,email:this.profile.email||''};this.success='Registered details updated.'}catch(e){this.error=errorMessage(e)}finally{this.busy=false}}}};
</script>